import React, { useState, useEffect, useContext } from 'react';
import { StyleSheet, Text, View, Image, ScrollView, TouchableOpacity, ActivityIndicator, Alert, Dimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { WebView } from 'react-native-webview';
import apiClient from '../../api/client';
import { AuthContext } from '../../context/AuthContext';

const { width } = Dimensions.get('window');

export default function EventDetailScreen({ route, navigation }) {
  const { eventId } = route.params;
  const { token, user } = useContext(AuthContext);
  const [event, setEvent] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [ticketQuantities, setTicketQuantities] = useState({});

  useEffect(() => {
    fetchEventDetails();
  }, [eventId]);

  const fetchEventDetails = async () => {
    try {
      const response = await apiClient.get(`/events/${eventId}`);
      if (response.data.status === 'success') {
        setEvent(response.data.event);
      }
    } catch (e) {
      console.error(e);
      Alert.alert('Erreur', 'Impossible de charger les détails de l\'événement.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleBuyTicket = (billet, quantity) => {
    if (event.is_past) {
      Alert.alert('Événement passé', 'Cet événement est déjà passé. Il n\'est plus possible d\'acheter de tickets.');
      return;
    }

    if (!token) {
      Alert.alert(
        'Connexion requise',
        'Veuillez vous connecter à votre compte pour acheter des billets.',
        [
          { text: 'Annuler', style: 'cancel' },
          { text: 'Se connecter', onPress: () => navigation.navigate('Login') }
        ]
      );
      return;
    }

    if (billet.quantite_disponible <= 0) {
      Alert.alert('Épuisé', 'Désolé, ce type de billet n\'est plus disponible.');
      return;
    }
    
    // Naviguer vers l'écran de paiement Stripe webview
    navigation.navigate('Checkout', {
      evenementId: event.id,
      billetId: billet.id,
      user: user,
      quantity: quantity || 1,
    });
  };

  if (isLoading) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#2563eb" />
      </View>
    );
  }

  if (!event) {
    return (
      <View style={styles.errorContainer}>
        <Text style={styles.errorText}>Événement non trouvé.</Text>
      </View>
    );
  }

  return (
    <ScrollView style={styles.container} contentContainerStyle={{ paddingBottom: 40 }} showsVerticalScrollIndicator={false}>
      {/* Background Image of Event */}
      <Image source={{ uri: event.photo_url }} style={styles.image} />
      
      {/* Detail Content */}
      <View style={styles.content}>
        <Text style={styles.category}>{event.categorie}</Text>
        <Text style={styles.title}>{event.titre}</Text>

        <Text style={styles.sectionTitle}>Infos Pratiques</Text>
        <View style={styles.infoBox}>
          <Text style={styles.infoText}>
            <Ionicons name="calendar-outline" size={16} color="#1e3a8a" /> Date : {event.date} à {event.start_heure}
          </Text>
          <Text style={styles.infoText}>
            <Ionicons name="location-outline" size={16} color="#1e3a8a" /> Lieu : {event.lieu}
          </Text>
          {event.nom_proprietaire && (
            <Text style={styles.infoText}>
              <Ionicons name="person-outline" size={16} color="#1e3a8a" /> Organisé par : {event.nom_proprietaire}
            </Text>
          )}
        </View>

        {event.description && (
          <>
            <Text style={styles.sectionTitle}>Description</Text>
            <Text style={styles.description}>{event.description}</Text>
          </>
        )}

        {/* Tickets Section */}
        <Text style={styles.sectionTitle}>Billets Disponibles</Text>
        {event.billets && event.billets.length > 0 ? (
          event.billets.map((billet) => {
            const qty = ticketQuantities[billet.id] || 1;
            const max = billet.quantite_disponible ?? 99;
            return (
              <View key={billet.id} style={styles.ticketCard}>
                <View style={styles.ticketInfo}>
                  <Text style={styles.ticketType}>{billet.type}</Text>
                  <Text style={styles.ticketDesc}>{billet.description || 'Accès standard à l\'événement'}</Text>
                  <Text style={styles.ticketAvailability}>
                    Reste : {billet.quantite_disponible} / {billet.quantite_totale}
                  </Text>
                </View>
                <View style={styles.ticketAction}>
                  <Text style={styles.ticketPrice}>{billet.prix} FCFA</Text>
                  {billet.quantite_disponible > 0 && !event.is_past && (
                    <View style={styles.quantityRow}>
                      <TouchableOpacity
                        onPress={() => {
                          if (qty > 1) {
                            setTicketQuantities({ ...ticketQuantities, [billet.id]: qty - 1 });
                          }
                        }}
                        style={styles.qtyBtn}
                      >
                        <Text style={styles.qtyBtnText}>-</Text>
                      </TouchableOpacity>
                      <Text style={styles.qtyText}>{qty}</Text>
                      <TouchableOpacity
                        onPress={() => {
                          if (qty < max) {
                            setTicketQuantities({ ...ticketQuantities, [billet.id]: qty + 1 });
                          }
                        }}
                        style={styles.qtyBtn}
                      >
                        <Text style={styles.qtyBtnText}>+</Text>
                      </TouchableOpacity>
                    </View>
                  )}
                  <TouchableOpacity
                    style={[
                      styles.buyButton,
                      (billet.quantite_disponible <= 0 || event.is_past) && styles.buyButtonDisabled,
                    ]}
                    onPress={() => handleBuyTicket(billet, qty)}
                    disabled={billet.quantite_disponible <= 0 || event.is_past}
                  >
                    <Text style={styles.buyButtonText}>
                      {event.is_past ? 'Événement passé' : (billet.quantite_disponible <= 0 ? 'Complet' : 'Réserver')}
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            );
          })
        ) : (
          <Text style={styles.noTickets}>Aucun billet configuré pour cet événement.</Text>
        )}

        {/* Vidéo de présentation — pleine largeur comme sur le site web */}
        {event.video_url && (
          <View style={styles.videoSection}>
            <View style={styles.videoHeader}>
              <Ionicons name="play-circle" size={20} color="#d9383a" />
              <Text style={styles.videoTitle}>Vidéo de présentation</Text>
            </View>
            <View style={styles.videoWrapper}>
              <WebView
                style={styles.videoPlayer}
                javaScriptEnabled={true}
                domStorageEnabled={true}
                allowsFullscreenVideo={true}
                mediaPlaybackRequiresUserAction={false}
                source={{
                  html: `<!DOCTYPE html>
<html>
<head>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    * { margin:0; padding:0; box-sizing:border-box; }
    body { background:#000; display:flex; align-items:center; justify-content:center; height:100vh; }
    video { width:100%; height:100%; object-fit:contain; }
  </style>
</head>
<body>
  <video src="${event.video_url}" controls playsinline preload="metadata"></video>
</body>
</html>`,
                }}
              />
            </View>
          </View>
        )}

        {/* Sponsors Section */}
        {event.sponsors && event.sponsors.length > 0 && (
          <>
            <Text style={styles.sectionTitle}>Sponsors</Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.sponsorsList}>
              {event.sponsors.map((sponsor) => (
                <View key={sponsor.id} style={styles.sponsorCard}>
                  {sponsor.logo_url ? (
                    <Image source={{ uri: sponsor.logo_url }} style={styles.sponsorLogo} />
                  ) : (
                    <View style={styles.sponsorLogoPlaceholder} />
                  )}
                  <Text style={styles.sponsorName}>{sponsor.nom}</Text>
                </View>
              ))}
            </ScrollView>
          </>
        )}
      </View>
    </ScrollView>
  );
}

